     * @param string $tz Birth place timezone: IANA name (Asia/Kolkata) or UTC offset (+05:30).
     * @param int $year Year (YYYY).
     * @param Ayanamsa|string|null $ayanamsa Sidereal ayanamsa (`Ayanamsa` case or value); the API
     *     uses Lahiri when left out.
     * @param HouseSystem|string|null $houseSystem House system (`HouseSystem` case or value), sent
     *     as `house_system`.
     * @param string|null $name Full name as written on official documents.
     * @param string|null $place
     * @param Lang|string|null $lang Response language: a `Lang` case or its code (`'hi'`, `'gu'`,
     *     ...). Sent as `lang` and `locale`.
     * @param RequestOptions|null $requestOptions Per-call timeout, raw body or onResponse hook.
     *
     * @return array<mixed> The decoded JSON response.
     *
     * @throws LifeAstroException On an API error or a network failure.
     */
    public function varshaphal(
        float $lat,
        float $lon,
        string $date,
        string $time,
        string $tz,
        int $year,
        Ayanamsa|string|null $ayanamsa = null,
        HouseSystem|string|null $houseSystem = null,
        ?string $name = null,
        ?string $place = null,
        Lang|string|null $lang = null,
        ?RequestOptions $requestOptions = null,
    ): array {
        $query = [];
        Query::put($query, 'lat', $lat);
        Query::put($query, 'lon', $lon);
        Query::put($query, 'date', $date);
        Query::put($query, 'time', $time);
        Query::put($query, 'tz', $tz);
        Query::put($query, 'ayanamsa', $ayanamsa);
        Query::put($query, 'house_system', $houseSystem);
        Query::put($query, 'name', $name);
        Query::put($query, 'place', $place);
        Query::put($query, 'year', $year);
        Query::put($query, 'lang', $lang);
        Query::put($query, 'locale', $lang);

        return $this->http->requestArray('/v1/reports/varshaphal', $query, $requestOptions);
    }
}
